INSERT INTO curriculum_nodes (id, slug, phase_id, order_index, title, subtitle, cs_foundation, ai_convergence, xp_reward, level_required, position_x, position_y, handbook_markdown, starter_code, test_suite, defense_prompts) VALUES
('node-5-11', 'phase-05-lesson-11-sql-execution-order-core-dialect-mechanic', 'module-7', 11, 'Lesson 7.11: SQL Execution Order & Core Dialect Mechanics', 'Prerequisites: Phase 2 (Lesson 2.1)', 'Prerequisites: Phase 2 (Lesson 2.1) | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 550.0, '# Lesson 5.11: SQL Execution Order & Core Dialect Mechanics

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 2 (Lesson 2.1)
- **Subtopics**:
  - `5.11.1` SQL physical processing order: `FROM` $	o$ `JOIN` $	o$ `WHERE` $	o$ `GROUP BY` $	o$ `HAVING` $	o$ `SELECT` $	o$ `DISTINCT` $	o$ `ORDER BY` $	o$ `LIMIT`.
  - `5.11.2` Why column aliases defined in `SELECT` cannot be referenced in `WHERE` clauses.
  - `5.11.3` NULL semantics: Three-Valued Logic (True, False, Unknown); `IS NULL` vs `= NULL` (which always evaluates to Unknown).
  - `5.11.4` Filtering grouped data: `WHERE` (filters rows before aggregation) vs `HAVING` (filters groups after aggregation).
- **Key Failure Modes & Edge Cases**: Writing `WHERE col = NULL` instead of `IS NULL`, causing queries to silently return zero rows.
- **Verification & Mastery Check**: Demonstrate how three-valued logic produces counter-intuitive results in `NOT IN` subqueries containing nulls.
- **Project Application**: SchemaVault: Raw SQL queries.', '{"solution.py": "# Phase 5 // Lesson 5.11: SQL Execution Order & Core Dialect Mechanics\n\ndef solve():\n    \"\"\"\n    Verification: Demonstrate how three-valued logic produces counter-intuitive results in `NOT IN` subqueries contain\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.11", "subtopics_count": 4, "verification_criteria": "Demonstrate how three-valued logic produces counter-intuitive results in `NOT IN` subqueries containing nulls.", "subtopics": ["5.11.1 SQL physical processing order: `FROM` $\to$ `JOIN` $\to$ `WHERE` $\to$ `GROUP BY` $\to$ `HAVING` $\to$ `SELECT` $\to$ `DISTINCT` $\to$ `ORDER BY` $\to$ `LIMIT`.", "5.11.2 Why column aliases defined in `SELECT` cannot be referenced in `WHERE` clauses.", "5.11.3 NULL semantics: Three-Valued Logic (True, False, Unknown); `IS NULL` vs `= NULL` (which always evaluates to Unknown).", "5.11.4 Filtering grouped data: `WHERE` (filters rows before aggregation) vs `HAVING` (filters groups after aggregation)."]}'::jsonb, '["Explain how this implementation prevents: Writing `WHERE col = NULL` instead of `IS NULL`, causing queries to silently return zero rows.", "How does SQL Execution Order & Core Dialect Mechanics scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-12', 'phase-05-lesson-12-joins-deep-dive-inner-outer-cross-self-jo', 'module-7', 12, 'Lesson 7.12: Joins Deep Dive: Inner, Outer, Cross, & Self Joins', 'Prerequisites: Lesson 5.11', 'Prerequisites: Lesson 5.11 | Subtopics: 6 items', 'Systems project application', 200, 6, 1250.0, 600.0, '# Lesson 5.12: Joins Deep Dive: Inner, Outer, Cross, & Self Joins

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.11
- **Subtopics**:
  - `5.12.1` Join mechanics: combining rows from two or more tables based on join predicates.
  - `5.12.2` `INNER JOIN`: intersection of matching rows.
  - `5.12.3` `LEFT OUTER JOIN` / `RIGHT OUTER JOIN`: preserving unmatched rows from left/right table with null-padding.
  - `5.12.4` `FULL OUTER JOIN`: union of matches and un-matches from both tables.
  - `5.12.5` `CROSS JOIN`: Cartesian product ($M 	imes N$ rows); generating test permutations.
  - `5.12.6` Self-Joins: joining a table to itself for hierarchical parent-child relationships.
- **Key Failure Modes & Edge Cases**: Accidental Cartesian explosion: missing join predicates in multi-table queries producing millions of unwanted rows.
- **Verification & Mastery Check**: Write a self-join query that identifies employees who earn more than their direct managers in a single query.
- **Project Application**: DataSift and SchemaVault.', '{"solution.py": "# Phase 5 // Lesson 5.12: Joins Deep Dive: Inner, Outer, Cross, & Self Joins\n\ndef solve():\n    \"\"\"\n    Verification: Write a self-join query that identifies employees who earn more than their direct managers in a sing\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.12", "subtopics_count": 6, "verification_criteria": "Write a self-join query that identifies employees who earn more than their direct managers in a single query.", "subtopics": ["5.12.1 Join mechanics: combining rows from two or more tables based on join predicates.", "5.12.2 `INNER JOIN`: intersection of matching rows.", "5.12.3 `LEFT OUTER JOIN` / `RIGHT OUTER JOIN`: preserving unmatched rows from left/right table with null-padding.", "5.12.4 `FULL OUTER JOIN`: union of matches and un-matches from both tables.", "5.12.5 `CROSS JOIN`: Cartesian product ($M \times N$ rows); generating test permutations.", "5.12.6 Self-Joins: joining a table to itself for hierarchical parent-child relationships."]}'::jsonb, '["Explain how this implementation prevents: Accidental Cartesian explosion: missing join predicates in multi-table queries producing millions of unwanted rows.", "How does Joins Deep Dive: Inner, Outer, Cross, & Self Joins scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-13', 'phase-05-lesson-13-subqueries-correlated-scalar-set-membersh', 'module-7', 13, 'Lesson 7.13: Subqueries: Correlated, Scalar, & Set Membership', 'Prerequisites: Lesson 5.12', 'Prerequisites: Lesson 5.12 | Subtopics: 4 items', 'Systems project application', 200, 6, 1310.0, 650.0, '# Lesson 5.13: Subqueries: Correlated, Scalar, & Set Membership

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.12
- **Subtopics**:
  - `5.13.1` Scalar Subqueries: subqueries returning a single row and single column for use in expressions.
  - `5.13.2` Subqueries in `FROM` clauses (Derived Tables): aliasing and materialization.
  - `5.13.3` `IN` vs `EXISTS`: why `EXISTS` short-circuits upon finding the first matching row.
  - `5.13.4` Correlated Subqueries: subqueries referencing columns from the outer query; row-by-row execution penalties.
- **Key Failure Modes & Edge Cases**: Using correlated subqueries inside `SELECT` lists across 100,000 rows, forcing 100,000 separate subquery executions.
- **Verification & Mastery Check**: Refactor an inefficient correlated subquery into a set-based `JOIN` with aggregation, measuring query speedup.
- **Project Application**: SchemaVault: Database migration queries.', '{"solution.py": "# Phase 5 // Lesson 5.13: Subqueries: Correlated, Scalar, & Set Membership\n\ndef solve():\n    \"\"\"\n    Verification: Refactor an inefficient correlated subquery into a set-based `JOIN` with aggregation, measuring quer\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.13", "subtopics_count": 4, "verification_criteria": "Refactor an inefficient correlated subquery into a set-based `JOIN` with aggregation, measuring query speedup.", "subtopics": ["5.13.1 Scalar Subqueries: subqueries returning a single row and single column for use in expressions.", "5.13.2 Subqueries in `FROM` clauses (Derived Tables): aliasing and materialization.", "5.13.3 `IN` vs `EXISTS`: why `EXISTS` short-circuits upon finding the first matching row.", "5.13.4 Correlated Subqueries: subqueries referencing columns from the outer query; row-by-row execution penalties."]}'::jsonb, '["Explain how this implementation prevents: Using correlated subqueries inside `SELECT` lists across 100,000 rows, forcing 100,000 separate subquery executions.", "How does Subqueries: Correlated, Scalar, & Set Membership scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-14', 'phase-05-lesson-14-data-manipulation-language-dml-upserts-re', 'module-7', 14, 'Lesson 7.14: Data Manipulation Language (DML): Upserts & RETURNING', 'Prerequisites: Lesson 5.11', 'Prerequisites: Lesson 5.11 | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 700.0, '# Lesson 5.14: Data Manipulation Language (DML): Upserts & RETURNING

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.11
- **Subtopics**:
  - `5.14.1` Atomic Upserts: `INSERT ... ON CONFLICT (id) DO UPDATE SET ...`.
  - `5.14.2` `ON CONFLICT DO NOTHING`: idempotent insertion patterns.
  - `5.14.3` The `RETURNING` clause: returning modified rows (`RETURNING id, created_at`) without issuing secondary queries.
  - `5.14.4` Multi-row batch inserts: parameterized batch syntax to maximize database throughput.
- **Key Failure Modes & Edge Cases**: Performing check-then-insert operations in separate application statements, introducing race conditions under concurrency.
- **Verification & Mastery Check**: Write an atomic batch upsert query in PostgreSQL using `ON CONFLICT` and `RETURNING`.
- **Project Application**: AuthForge: User profile upserts.', '{"solution.py": "# Phase 5 // Lesson 5.14: Data Manipulation Language (DML): Upserts & RETURNING\n\ndef solve():\n    \"\"\"\n    Verification: Write an atomic batch upsert query in PostgreSQL using `ON CONFLICT` and `RETURNING`.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.14", "subtopics_count": 4, "verification_criteria": "Write an atomic batch upsert query in PostgreSQL using `ON CONFLICT` and `RETURNING`.", "subtopics": ["5.14.1 Atomic Upserts: `INSERT ... ON CONFLICT (id) DO UPDATE SET ...`.", "5.14.2 `ON CONFLICT DO NOTHING`: idempotent insertion patterns.", "5.14.3 The `RETURNING` clause: returning modified rows (`RETURNING id, created_at`) without issuing secondary queries.", "5.14.4 Multi-row batch inserts: parameterized batch syntax to maximize database throughput."]}'::jsonb, '["Explain how this implementation prevents: Performing check-then-insert operations in separate application statements, introducing race conditions under concurrenc", "How does Data Manipulation Language (DML): Upserts & RETURNING scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-15', 'phase-05-lesson-15-data-definition-language-ddl-constraints-', 'module-7', 15, 'Lesson 7.15: Data Definition Language (DDL): Constraints & Alter Table', 'Prerequisites: Lesson 5.9', 'Prerequisites: Lesson 5.9 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 750.0, '# Lesson 5.15: Data Definition Language (DDL): Constraints & Alter Table

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.9
- **Subtopics**:
  - `5.15.1` Integrity constraints: `PRIMARY KEY`, `FOREIGN KEY` (referential integrity), `UNIQUE`, `CHECK`, `NOT NULL`.
  - `5.15.2` Foreign key cascade options: `ON DELETE CASCADE`, `ON DELETE SET NULL`, `ON DELETE RESTRICT`.
  - `5.15.3` Zero-downtime schema changes: adding nullable columns vs columns with default values.
  - `5.15.4` PostgreSQL Table Locks during `ALTER TABLE`: avoiding exclusive `ACCESS EXCLUSIVE` table locks in production.
- **Key Failure Modes & Edge Cases**: Adding a column with a dynamic default value on a 50M-row table, taking an exclusive lock and freezing web traffic for minutes.
- **Verification & Mastery Check**: Execute a zero-downtime migration in PostgreSQL that safely adds a column with default values to an active table.
- **Project Application**: SchemaVault: Core migration tool features.', '{"solution.py": "# Phase 5 // Lesson 5.15: Data Definition Language (DDL): Constraints & Alter Table\n\ndef solve():\n    \"\"\"\n    Verification: Execute a zero-downtime migration in PostgreSQL that safely adds a column with default values to an \n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.15", "subtopics_count": 4, "verification_criteria": "Execute a zero-downtime migration in PostgreSQL that safely adds a column with default values to an active table.", "subtopics": ["5.15.1 Integrity constraints: `PRIMARY KEY`, `FOREIGN KEY` (referential integrity), `UNIQUE`, `CHECK`, `NOT NULL`.", "5.15.2 Foreign key cascade options: `ON DELETE CASCADE`, `ON DELETE SET NULL`, `ON DELETE RESTRICT`.", "5.15.3 Zero-downtime schema changes: adding nullable columns vs columns with default values.", "5.15.4 PostgreSQL Table Locks during `ALTER TABLE`: avoiding exclusive `ACCESS EXCLUSIVE` table locks in production."]}'::jsonb, '["Explain how this implementation prevents: Adding a column with a dynamic default value on a 50M-row table, taking an exclusive lock and freezing web traffic for m", "How does Data Definition Language (DDL): Constraints & Alter Table scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-16', 'phase-05-lesson-16-postgresql-power-features-jsonb-arrays-tr', 'module-7', 16, 'Lesson 7.16: PostgreSQL Power Features: JSONB, Arrays, & Trigrams', 'Prerequisites: Lesson 5.15', 'Prerequisites: Lesson 5.15 | Subtopics: 4 items', 'Systems project application', 200, 6, 1310.0, 800.0, '# Lesson 5.16: PostgreSQL Power Features: JSONB, Arrays, & Trigrams

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.15
- **Subtopics**:
  - `5.16.1` `JSONB` datatype: binary-format indexed JSON storage; containment operators (`@>`), key extraction (`->`, `->>`).
  - `5.16.2` Indexing JSONB: GIN (Generalized Inverted Index) for fast key/value queries on unstructured attributes.
  - `5.16.3` PostgreSQL native Arrays: `text[]`, `integer[]`, array containment (`&&`, `@>`).
  - `5.16.4` Fuzzy text search with `pg_trgm`: trigram matching and GIN/GiST similarity queries (`%` operator).
- **Key Failure Modes & Edge Cases**: Using `JSON` instead of `JSONB`, losing binary compression and forcing re-parsing on every query.
- **Verification & Mastery Check**: Build a fuzzy product search query using `pg_trgm` that handles misspellings on an indexed million-row table.
- **Project Application**: DocuMind and TenantIQ.', '{"solution.py": "# Phase 5 // Lesson 5.16: PostgreSQL Power Features: JSONB, Arrays, & Trigrams\n\ndef solve():\n    \"\"\"\n    Verification: Build a fuzzy product search query using `pg_trgm` that handles misspellings on an indexed million-r\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.16", "subtopics_count": 4, "verification_criteria": "Build a fuzzy product search query using `pg_trgm` that handles misspellings on an indexed million-row table.", "subtopics": ["5.16.1 `JSONB` datatype: binary-format indexed JSON storage; containment operators (`@>`), key extraction (`->`, `->>`).", "5.16.2 Indexing JSONB: GIN (Generalized Inverted Index) for fast key/value queries on unstructured attributes.", "5.16.3 PostgreSQL native Arrays: `text[]`, `integer[]`, array containment (`&&`, `@>`).", "5.16.4 Fuzzy text search with `pg_trgm`: trigram matching and GIN/GiST similarity queries (`%` operator)."]}'::jsonb, '["Explain how this implementation prevents: Using `JSON` instead of `JSONB`, losing binary compression and forcing re-parsing on every query.", "How does PostgreSQL Power Features: JSONB, Arrays, & Trigrams scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-17', 'phase-05-lesson-17-window-functions-foundations-partitions-o', 'module-7', 17, 'Lesson 7.17: Window Functions Foundations: Partitions & Ordering', 'Prerequisites: Lesson 5.11', 'Prerequisites: Lesson 5.11 | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 850.0, '# Lesson 5.17: Window Functions Foundations: Partitions & Ordering

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.11
- **Subtopics**:
  - `5.17.1` The Window Function concept: computing row-level analytics across subsets without collapsing rows via `GROUP BY`.
  - `5.17.2` The `OVER()` clause: `PARTITION BY` (segmenting data) and `ORDER BY` (establishing evaluation sequence).
  - `5.17.3` Aggregate window functions: `SUM() OVER(...)`, `AVG() OVER(...)`, `COUNT() OVER(...)`.
  - `5.17.4` Mixing row attributes with group aggregates in a single query pass.
- **Key Failure Modes & Edge Cases**: Confusing `PARTITION BY` in window functions with `GROUP BY`, expecting rows to collapse.
- **Verification & Mastery Check**: Write a query calculating each transaction''s percentage contribution to its user''s total monthly spend.
- **Project Application**: TenantIQ: DORA metrics calculation.', '{"solution.py": "# Phase 5 // Lesson 5.17: Window Functions Foundations: Partitions & Ordering\n\ndef solve():\n    \"\"\"\n    Verification: Write a query calculating each transaction''s percentage contribution to its user''s total monthly spe\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.17", "subtopics_count": 4, "verification_criteria": "Write a query calculating each transaction''s percentage contribution to its user''s total monthly spend.", "subtopics": ["5.17.1 The Window Function concept: computing row-level analytics across subsets without collapsing rows via `GROUP BY`.", "5.17.2 The `OVER()` clause: `PARTITION BY` (segmenting data) and `ORDER BY` (establishing evaluation sequence).", "5.17.3 Aggregate window functions: `SUM() OVER(...)`, `AVG() OVER(...)`, `COUNT() OVER(...)`.", "5.17.4 Mixing row attributes with group aggregates in a single query pass."]}'::jsonb, '["Explain how this implementation prevents: Confusing `PARTITION BY` in window functions with `GROUP BY`, expecting rows to collapse.", "How does Window Functions Foundations: Partitions & Ordering scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-18', 'phase-05-lesson-18-ranking-window-functions-row-number-rank-', 'module-7', 18, 'Lesson 7.18: Ranking Window Functions: `ROW_NUMBER`, `RANK`, `DENSE_RANK`', 'Prerequisites: Lesson 5.17', 'Prerequisites: Lesson 5.17 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 900.0, '# Lesson 5.18: Ranking Window Functions: `ROW_NUMBER`, `RANK`, `DENSE_RANK`

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.17
- **Subtopics**:
  - `5.18.1` `ROW_NUMBER()`: sequential integer assigned to each row within partition, breaking ties deterministically.
  - `5.18.2` `RANK()`: assigns identical rank to tied values, skipping subsequent ranks (1, 2, 2, 4).
  - `5.18.3` `DENSE_RANK()`: assigns identical rank to tied values without skipping subsequent ranks (1, 2, 2, 3).
  - `5.18.4` `NTILE(n)`: dividing partitions into $n$ equal frequency buckets (percentiles, quartiles).
- **Key Failure Modes & Edge Cases**: Using `ROW_NUMBER` for leaderboards where ties exist, arbitrarily ranking tied users differently without deterministic secondary sorts.
- **Verification & Mastery Check**: Write a query that extracts the top 3 highest spending customers per region using `DENSE_RANK()`.
- **Project Application**: DataSift: Top-N analysis.', '{"solution.py": "# Phase 5 // Lesson 5.18: Ranking Window Functions: `ROW_NUMBER`, `RANK`, `DENSE_RANK`\n\ndef solve():\n    \"\"\"\n    Verification: Write a query that extracts the top 3 highest spending customers per region using `DENSE_RANK()`.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.18", "subtopics_count": 4, "verification_criteria": "Write a query that extracts the top 3 highest spending customers per region using `DENSE_RANK()`.", "subtopics": ["5.18.1 `ROW_NUMBER()`: sequential integer assigned to each row within partition, breaking ties deterministically.", "5.18.2 `RANK()`: assigns identical rank to tied values, skipping subsequent ranks (1, 2, 2, 4).", "5.18.3 `DENSE_RANK()`: assigns identical rank to tied values without skipping subsequent ranks (1, 2, 2, 3).", "5.18.4 `NTILE(n)`: dividing partitions into $n$ equal frequency buckets (percentiles, quartiles)."]}'::jsonb, '["Explain how this implementation prevents: Using `ROW_NUMBER` for leaderboards where ties exist, arbitrarily ranking tied users differently without deterministic s", "How does Ranking Window Functions: `ROW_NUMBER`, `RANK`, `DENSE_RANK` scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-19', 'phase-05-lesson-19-value-window-functions-lag-lead-offsets', 'module-7', 19, 'Lesson 7.19: Value Window Functions: `LAG`, `LEAD`, & Offsets', 'Prerequisites: Lesson 5.17', 'Prerequisites: Lesson 5.17 | Subtopics: 4 items', 'Systems project application', 200, 6, 1310.0, 950.0, '# Lesson 5.19: Value Window Functions: `LAG`, `LEAD`, & Offsets

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.17
- **Subtopics**:
  - `5.19.1` `LAG(col, offset, default)`: accessing values from preceding rows within partition.
  - `5.19.2` `LEAD(col, offset, default)`: accessing values from subsequent rows within partition.
  - `5.19.3` `FIRST_VALUE()` and `LAST_VALUE()`: boundary value retrieval.
  - `5.19.4` Period-over-period calculations: computing day-over-day growth rates and time elapsed between user events.
- **Key Failure Modes & Edge Cases**: Calling `LAST_VALUE()` with default window framing, returning current row value instead of true partition end.
- **Verification & Mastery Check**: Calculate the time delta in minutes between consecutive user login events across a dataset using `LAG()`.
- **Project Application**: TenantIQ: Lead Time for Changes calculation.', '{"solution.py": "# Phase 5 // Lesson 5.19: Value Window Functions: `LAG`, `LEAD`, & Offsets\n\ndef solve():\n    \"\"\"\n    Verification: Calculate the time delta in minutes between consecutive user login events across a dataset using `LA\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.19", "subtopics_count": 4, "verification_criteria": "Calculate the time delta in minutes between consecutive user login events across a dataset using `LAG()`.", "subtopics": ["5.19.1 `LAG(col, offset, default)`: accessing values from preceding rows within partition.", "5.19.2 `LEAD(col, offset, default)`: accessing values from subsequent rows within partition.", "5.19.3 `FIRST_VALUE()` and `LAST_VALUE()`: boundary value retrieval.", "5.19.4 Period-over-period calculations: computing day-over-day growth rates and time elapsed between user events."]}'::jsonb, '["Explain how this implementation prevents: Calling `LAST_VALUE()` with default window framing, returning current row value instead of true partition end.", "How does Value Window Functions: `LAG`, `LEAD`, & Offsets scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-20', 'phase-05-lesson-20-window-framing-physical-rows-vs-logical-r', 'module-7', 20, 'Lesson 7.20: Window Framing: Physical Rows vs Logical Ranges', 'Prerequisites: Lesson 5.17', 'Prerequisites: Lesson 5.17 | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 1000.0, '# Lesson 5.20: Window Framing: Physical Rows vs Logical Ranges

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.17
- **Subtopics**:
  - `5.20.1` The Window Frame: specifying exact sliding row subsets within the ordered partition.
  - `5.20.2` `ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`: cumulative running totals.
  - `5.20.3` `ROWS BETWEEN 6 PRECEDING AND CURRENT ROW`: 7-day rolling moving averages.
  - `5.20.4` `RANGE` framing: evaluating offsets based on logical value differences rather than physical row counts.
- **Key Failure Modes & Edge Cases**: Omitting explicit window framing on `ORDER BY` window queries, triggering default framing that degrades query speed.
- **Verification & Mastery Check**: Implement a 30-day moving average and a cumulative sum of daily active users in a single SQL query.
- **Project Application**: TenantIQ: DORA metrics rolling averages.', '{"solution.py": "# Phase 5 // Lesson 5.20: Window Framing: Physical Rows vs Logical Ranges\n\ndef solve():\n    \"\"\"\n    Verification: Implement a 30-day moving average and a cumulative sum of daily active users in a single SQL query.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.20", "subtopics_count": 4, "verification_criteria": "Implement a 30-day moving average and a cumulative sum of daily active users in a single SQL query.", "subtopics": ["5.20.1 The Window Frame: specifying exact sliding row subsets within the ordered partition.", "5.20.2 `ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`: cumulative running totals.", "5.20.3 `ROWS BETWEEN 6 PRECEDING AND CURRENT ROW`: 7-day rolling moving averages.", "5.20.4 `RANGE` framing: evaluating offsets based on logical value differences rather than physical row counts."]}'::jsonb, '["Explain how this implementation prevents: Omitting explicit window framing on `ORDER BY` window queries, triggering default framing that degrades query speed.", "How does Window Framing: Physical Rows vs Logical Ranges scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-21', 'phase-05-lesson-21-common-table-expressions-ctes-clean-query', 'module-7', 21, 'Lesson 7.21: Common Table Expressions (CTEs): Clean Query Pipelines', 'Prerequisites: Lesson 5.11', 'Prerequisites: Lesson 5.11 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 1050.0, '# Lesson 5.21: Common Table Expressions (CTEs): Clean Query Pipelines

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.11
- **Subtopics**:
  - `5.21.1` The CTE syntax: `WITH cte_name AS (SELECT ...) SELECT ... FROM cte_name`.
  - `5.21.2` Query readability: breaking massive, unmaintainable subquery joins into step-by-step readable modules.
  - `5.21.3` PostgreSQL CTE Optimization: `AS MATERIALIZED` vs `AS NOT MATERIALIZED` (inlined query pushdown).
  - `5.21.4` Multiple CTE chaining: composing multi-stage transformation pipelines.
- **Key Failure Modes & Edge Cases**: Accidental materialization fences in older PostgreSQL versions preventing index pushdown predicates into CTEs.
- **Verification & Mastery Check**: Refactor an unreadable 4-level nested subquery into a clean 3-stage CTE pipeline.
- **Project Application**: SchemaVault and TenantIQ.', '{"solution.py": "# Phase 5 // Lesson 5.21: Common Table Expressions (CTEs): Clean Query Pipelines\n\ndef solve():\n    \"\"\"\n    Verification: Refactor an unreadable 4-level nested subquery into a clean 3-stage CTE pipeline.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.21", "subtopics_count": 4, "verification_criteria": "Refactor an unreadable 4-level nested subquery into a clean 3-stage CTE pipeline.", "subtopics": ["5.21.1 The CTE syntax: `WITH cte_name AS (SELECT ...) SELECT ... FROM cte_name`.", "5.21.2 Query readability: breaking massive, unmaintainable subquery joins into step-by-step readable modules.", "5.21.3 PostgreSQL CTE Optimization: `AS MATERIALIZED` vs `AS NOT MATERIALIZED` (inlined query pushdown).", "5.21.4 Multiple CTE chaining: composing multi-stage transformation pipelines."]}'::jsonb, '["Explain how this implementation prevents: Accidental materialization fences in older PostgreSQL versions preventing index pushdown predicates into CTEs.", "How does Common Table Expressions (CTEs): Clean Query Pipelines scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-22', 'phase-05-lesson-22-recursive-ctes-hierarchies-trees-graphs-i', 'module-7', 22, 'Lesson 7.22: Recursive CTEs: Hierarchies, Trees, & Graphs in SQL', 'Prerequisites: Lesson 5.21', 'Prerequisites: Lesson 5.21 | Subtopics: 4 items', 'Systems project application', 200, 6, 1310.0, 1100.0, '# Lesson 5.22: Recursive CTEs: Hierarchies, Trees, & Graphs in SQL

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.21
- **Subtopics**:
  - `5.22.1` Recursive CTE architecture: `WITH RECURSIVE`; Anchor member $	o$ `UNION ALL` $	o$ Recursive member.
  - `5.22.2` Termination conditions: recursion halting when recursive member returns zero rows.
  - `5.22.3` Tree traversal in SQL: calculating node depth, path strings, and subtree aggregations (org charts, categories).
  - `5.22.4` Cycle prevention: tracking visited node arrays (`ARRAY[id]`) to prevent infinite recursion on cyclic graphs.
- **Key Failure Modes & Edge Cases**: Infinite recursion in recursive CTEs caused by cyclic graph data, crashing database backends via memory exhaustion.
- **Verification & Mastery Check**: Write a recursive CTE that traverses a category hierarchy of arbitrary depth and outputs the full breadcrumb path for every node.
- **Project Application**: TenantIQ: Team and organization permission hierarchy.', '{"solution.py": "# Phase 5 // Lesson 5.22: Recursive CTEs: Hierarchies, Trees, & Graphs in SQL\n\ndef solve():\n    \"\"\"\n    Verification: Write a recursive CTE that traverses a category hierarchy of arbitrary depth and outputs the full br\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.22", "subtopics_count": 4, "verification_criteria": "Write a recursive CTE that traverses a category hierarchy of arbitrary depth and outputs the full breadcrumb path for every node.", "subtopics": ["5.22.1 Recursive CTE architecture: `WITH RECURSIVE`; Anchor member $\to$ `UNION ALL` $\to$ Recursive member.", "5.22.2 Termination conditions: recursion halting when recursive member returns zero rows.", "5.22.3 Tree traversal in SQL: calculating node depth, path strings, and subtree aggregations (org charts, categories).", "5.22.4 Cycle prevention: tracking visited node arrays (`ARRAY[id]`) to prevent infinite recursion on cyclic graphs."]}'::jsonb, '["Explain how this implementation prevents: Infinite recursion in recursive CTEs caused by cyclic graph data, crashing database backends via memory exhaustion.", "How does Recursive CTEs: Hierarchies, Trees, & Graphs in SQL scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-23', 'phase-05-lesson-23-postgresql-physical-storage-heap-files-pa', 'module-7', 23, 'Lesson 7.23: PostgreSQL Physical Storage: Heap Files, Pages, & Tuples', 'Prerequisites: Phase 0 (Lesson 0.9)', 'Prerequisites: Phase 0 (Lesson 0.9) | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 1150.0, '# Lesson 5.23: PostgreSQL Physical Storage: Heap Files, Pages, & Tuples

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0 (Lesson 0.9)
- **Subtopics**:
  - `5.23.1` Database Cluster architecture: Database $	o$ Tablespace $	o$ Relational File $	o$ 8KB Pages.
  - `5.23.2` Page anatomy: Page Header (24 bytes), Item Identifiers (Line Pointers), Free Space, Tuple Data.
  - `5.23.3` The Tuple ID (`ctid`): physical address identifier `(block_number, offset_number)`.
  - `5.23.4` Heap-Only Tuples (HOT): updating tuples within the same 8KB page without modifying index pointers.
- **Key Failure Modes & Edge Cases**: Assuming database rows are stored contiguously on disk in primary key order (PostgreSQL uses un-ordered heap files).
- **Verification & Mastery Check**: Inspect raw tuple headers and `ctid` pointers using the `pageinspect` PostgreSQL extension.
- **Project Application**: Database internals mastery.', '{"solution.py": "# Phase 5 // Lesson 5.23: PostgreSQL Physical Storage: Heap Files, Pages, & Tuples\n\ndef solve():\n    \"\"\"\n    Verification: Inspect raw tuple headers and `ctid` pointers using the `pageinspect` PostgreSQL extension.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.23", "subtopics_count": 4, "verification_criteria": "Inspect raw tuple headers and `ctid` pointers using the `pageinspect` PostgreSQL extension.", "subtopics": ["5.23.1 Database Cluster architecture: Database $\to$ Tablespace $\to$ Relational File $\to$ 8KB Pages.", "5.23.2 Page anatomy: Page Header (24 bytes), Item Identifiers (Line Pointers), Free Space, Tuple Data.", "5.23.3 The Tuple ID (`ctid`): physical address identifier `(block_number, offset_number)`.", "5.23.4 Heap-Only Tuples (HOT): updating tuples within the same 8KB page without modifying index pointers."]}'::jsonb, '["Explain how this implementation prevents: Assuming database rows are stored contiguously on disk in primary key order (PostgreSQL uses un-ordered heap files).", "How does PostgreSQL Physical Storage: Heap Files, Pages, & Tuples scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-24', 'phase-05-lesson-24-b-tree-index-architecture-search-depth', 'module-7', 24, 'Lesson 7.24: B-Tree Index Architecture & Search Depth', 'Prerequisites: Phase 3 (Lesson 3.15), Lesson 5.23', 'Prerequisites: Phase 3 (Lesson 3.15), Lesson 5.23 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 1200.0, '# Lesson 5.24: B-Tree Index Architecture & Search Depth

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 3 (Lesson 3.15), Lesson 5.23
- **Subtopics**:
  - `5.24.1` B-Tree index structure in PostgreSQL: Metapage, Root page, Internal branch pages, Leaf pages.
  - `5.24.2` High Fan-Out: each 8KB index page storing hundreds of keys; logarithmic search depth ($O(\log n)$, depth 3 for 10M rows).
  - `5.24.3` Leaf page structure: sorted keys and pointer arrays to heap `ctid` entries; bidirectional sibling pointers.
  - `5.24.4` Index Traversal: traversing from root to leaf to obtain `ctid`, then fetching physical page from heap.
- **Key Failure Modes & Edge Cases**: Creating single-column indexes on every table column, multiplying write amplification without aiding composite queries.
- **Verification & Mastery Check**: Calculate the exact B-Tree depth and page count for a table with 50 million 64-bit integer records.
- **Project Application**: SchemaVault: Index design.', '{"solution.py": "# Phase 5 // Lesson 5.24: B-Tree Index Architecture & Search Depth\n\ndef solve():\n    \"\"\"\n    Verification: Calculate the exact B-Tree depth and page count for a table with 50 million 64-bit integer records.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.24", "subtopics_count": 4, "verification_criteria": "Calculate the exact B-Tree depth and page count for a table with 50 million 64-bit integer records.", "subtopics": ["5.24.1 B-Tree index structure in PostgreSQL: Metapage, Root page, Internal branch pages, Leaf pages.", "5.24.2 High Fan-Out: each 8KB index page storing hundreds of keys; logarithmic search depth ($O(\\log n)$, depth 3 for 10M rows).", "5.24.3 Leaf page structure: sorted keys and pointer arrays to heap `ctid` entries; bidirectional sibling pointers.", "5.24.4 Index Traversal: traversing from root to leaf to obtain `ctid`, then fetching physical page from heap."]}'::jsonb, '["Explain how this implementation prevents: Creating single-column indexes on every table column, multiplying write amplification without aiding composite queries.", "How does B-Tree Index Architecture & Search Depth scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-25', 'phase-05-lesson-25-composite-indexes-the-leftmost-prefix-rul', 'module-7', 25, 'Lesson 7.25: Composite Indexes & The Leftmost Prefix Rule', 'Prerequisites: Lesson 5.24', 'Prerequisites: Lesson 5.24 | Subtopics: 4 items', 'Systems project application', 200, 6, 1310.0, 1250.0, '# Lesson 5.25: Composite Indexes & The Leftmost Prefix Rule

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.24
- **Subtopics**:
  - `5.25.1` Composite Index structure: index on multiple columns `(tenant_id, status, created_at)`.
  - `5.25.2` The Leftmost Prefix Rule: an index on `(A, B, C)` accelerates queries on `A`, `(A, B)`, and `(A, B, C)`; useless for queries on `B` alone.
  - `5.25.3` Column ordering heuristics: placing equality columns first, followed by range/sort columns.
  - `5.25.4` Index Skip Scans: how modern engines emulate multi-column indexing across low-cardinality prefixes.
- **Key Failure Modes & Edge Cases**: Ordering composite index columns as `(created_at, tenant_id)`, rendering the index useless for queries filtering on `tenant_id` alone.
- **Verification & Mastery Check**: Design the optimal composite index for an API query filtering by tenant, filtering by date range, and sorting by ID.
- **Project Application**: TenantIQ: Composite metric indexes.', '{"solution.py": "# Phase 5 // Lesson 5.25: Composite Indexes & The Leftmost Prefix Rule\n\ndef solve():\n    \"\"\"\n    Verification: Design the optimal composite index for an API query filtering by tenant, filtering by date range, an\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.25", "subtopics_count": 4, "verification_criteria": "Design the optimal composite index for an API query filtering by tenant, filtering by date range, and sorting by ID.", "subtopics": ["5.25.1 Composite Index structure: index on multiple columns `(tenant_id, status, created_at)`.", "5.25.2 The Leftmost Prefix Rule: an index on `(A, B, C)` accelerates queries on `A`, `(A, B)`, and `(A, B, C)`; useless for queries on `B` alone.", "5.25.3 Column ordering heuristics: placing equality columns first, followed by range/sort columns.", "5.25.4 Index Skip Scans: how modern engines emulate multi-column indexing across low-cardinality prefixes."]}'::jsonb, '["Explain how this implementation prevents: Ordering composite index columns as `(created_at, tenant_id)`, rendering the index useless for queries filtering on `ten", "How does Composite Indexes & The Leftmost Prefix Rule scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-26', 'phase-05-lesson-26-covering-indexes-index-only-scans', 'module-7', 26, 'Lesson 7.26: Covering Indexes & Index-Only Scans', 'Prerequisites: Lesson 5.24', 'Prerequisites: Lesson 5.24 | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 1300.0, '# Lesson 5.26: Covering Indexes & Index-Only Scans

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.24
- **Subtopics**:
  - `5.26.1` The Cost of Heap Lookups: fetching heap pages after scanning index leaf pages.
  - `5.26.2` Index-Only Scan: satisfying query columns entirely from the index without accessing the heap table.
  - `5.26.3` The `INCLUDE` clause: `CREATE INDEX ... ON orders (user_id) INCLUDE (amount, status)`.
  - `5.26.4` The Visibility Map (VM): why Index-Only scans must check the VM to confirm all tuples on the heap page are visible to all transactions.
- **Key Failure Modes & Edge Cases**: Assuming an index scan will be an Index-Only scan when the Visibility Map is dirty due to lack of vacuuming.
- **Verification & Mastery Check**: Create a covering index with `INCLUDE` and prove using `EXPLAIN` that the query executes an Index-Only Scan with zero heap fetches.
- **Project Application**: AuthForge: High-speed token validation query.', '{"solution.py": "# Phase 5 // Lesson 5.26: Covering Indexes & Index-Only Scans\n\ndef solve():\n    \"\"\"\n    Verification: Create a covering index with `INCLUDE` and prove using `EXPLAIN` that the query executes an Index-On\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.26", "subtopics_count": 4, "verification_criteria": "Create a covering index with `INCLUDE` and prove using `EXPLAIN` that the query executes an Index-Only Scan with zero heap fetches.", "subtopics": ["5.26.1 The Cost of Heap Lookups: fetching heap pages after scanning index leaf pages.", "5.26.2 Index-Only Scan: satisfying query columns entirely from the index without accessing the heap table.", "5.26.3 The `INCLUDE` clause: `CREATE INDEX ... ON orders (user_id) INCLUDE (amount, status)`.", "5.26.4 The Visibility Map (VM): why Index-Only scans must check the VM to confirm all tuples on the heap page are visible to all transactions."]}'::jsonb, '["Explain how this implementation prevents: Assuming an index scan will be an Index-Only scan when the Visibility Map is dirty due to lack of vacuuming.", "How does Covering Indexes & Index-Only Scans scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-27', 'phase-05-lesson-27-specialized-indexes-partial-expression-gi', 'module-7', 27, 'Lesson 7.27: Specialized Indexes: Partial, Expression, GIN, & BRIN', 'Prerequisites: Lesson 5.24', 'Prerequisites: Lesson 5.24 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 1350.0, '# Lesson 5.27: Specialized Indexes: Partial, Expression, GIN, & BRIN

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.24
- **Subtopics**:
  - `5.27.1` Partial Indexes: `CREATE INDEX ... WHERE status = ''pending''`; indexing 1% of active data, saving 99% RAM.
  - `5.27.2` Expression Indexes: `CREATE INDEX ... ON users (LOWER(email))`; accelerating function calls in `WHERE` clauses.
  - `5.27.3` Generalized Inverted Index (GIN): indexing composite items (JSONB keys, array elements, text tokens).
  - `5.27.4` Block Range Index (BRIN): storing min/max values per disk block range; tiny footprint for append-only time-series data.
- **Key Failure Modes & Edge Cases**: Creating a standard B-Tree index on a timestamp column in an append-only 1TB time-series table instead of a BRIN index (saving 99% space).
- **Verification & Mastery Check**: Compare index size and query speed of B-Tree vs BRIN on an append-only 10M row table.
- **Project Application**: TenantIQ: Metric event indexing.', '{"solution.py": "# Phase 5 // Lesson 5.27: Specialized Indexes: Partial, Expression, GIN, & BRIN\n\ndef solve():\n    \"\"\"\n    Verification: Compare index size and query speed of B-Tree vs BRIN on an append-only 10M row table.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.27", "subtopics_count": 4, "verification_criteria": "Compare index size and query speed of B-Tree vs BRIN on an append-only 10M row table.", "subtopics": ["5.27.1 Partial Indexes: `CREATE INDEX ... WHERE status = ''pending''`; indexing 1% of active data, saving 99% RAM.", "5.27.2 Expression Indexes: `CREATE INDEX ... ON users (LOWER(email))`; accelerating function calls in `WHERE` clauses.", "5.27.3 Generalized Inverted Index (GIN): indexing composite items (JSONB keys, array elements, text tokens).", "5.27.4 Block Range Index (BRIN): storing min/max values per disk block range; tiny footprint for append-only time-series data."]}'::jsonb, '["Explain how this implementation prevents: Creating a standard B-Tree index on a timestamp column in an append-only 1TB time-series table instead of a BRIN index (", "How does Specialized Indexes: Partial, Expression, GIN, & BRIN scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-28', 'phase-05-lesson-28-query-execution-plan-analysis-with-explai', 'module-7', 28, 'Lesson 7.28: Query Execution Plan Analysis with `EXPLAIN (ANALYZE, BUFFERS)`', 'Prerequisites: Lesson 5.23–5.27', 'Prerequisites: Lesson 5.23–5.27 | Subtopics: 5 items', 'Systems project application', 200, 6, 1310.0, 1400.0, '# Lesson 5.28: Query Execution Plan Analysis with `EXPLAIN (ANALYZE, BUFFERS)`

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.23–5.27
- **Subtopics**:
  - `5.28.1` The PostgreSQL Query Optimizer: cost-based planner, sequential page cost (`seq_page_cost`), random page cost (`random_page_cost`).
  - `5.28.2` `EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON)`: executing queries and measuring real execution time vs estimated costs.
  - `5.28.3` Interpreting scan nodes: `Seq Scan`, `Index Scan`, `Index Only Scan`, `Bitmap Index Scan` + `Bitmap Heap Scan`.
  - `5.28.4` Interpreting join nodes: `Nested Loop` (small datasets), `Hash Join` (unsorted large sets), `Merge Join` (pre-sorted sets).
  - `5.28.5` Buffer hit ratio analysis: counting `Buffers: shared hit` (RAM) vs `read` (disk).
- **Key Failure Modes & Edge Cases**: Misinterpreting query plan estimates (`cost=...`) as actual milliseconds without running `EXPLAIN ANALYZE`.
- **Verification & Mastery Check**: Analyze a complex slow query plan, identify sequential scans and buffer reads, create targeted indexes, and achieve 50x speedup.
- **Project Application**: AuthForge and TenantIQ: Database query optimization.', '{"solution.py": "# Phase 5 // Lesson 5.28: Query Execution Plan Analysis with `EXPLAIN (ANALYZE, BUFFERS)`\n\ndef solve():\n    \"\"\"\n    Verification: Analyze a complex slow query plan, identify sequential scans and buffer reads, create targeted index\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.28", "subtopics_count": 5, "verification_criteria": "Analyze a complex slow query plan, identify sequential scans and buffer reads, create targeted indexes, and achieve 50x speedup.", "subtopics": ["5.28.1 The PostgreSQL Query Optimizer: cost-based planner, sequential page cost (`seq_page_cost`), random page cost (`random_page_cost`).", "5.28.2 `EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON)`: executing queries and measuring real execution time vs estimated costs.", "5.28.3 Interpreting scan nodes: `Seq Scan`, `Index Scan`, `Index Only Scan`, `Bitmap Index Scan` + `Bitmap Heap Scan`.", "5.28.4 Interpreting join nodes: `Nested Loop` (small datasets), `Hash Join` (unsorted large sets), `Merge Join` (pre-sorted sets).", "5.28.5 Buffer hit ratio analysis: counting `Buffers: shared hit` (RAM) vs `read` (disk)."]}'::jsonb, '["Explain how this implementation prevents: Misinterpreting query plan estimates (`cost=...`) as actual milliseconds without running `EXPLAIN ANALYZE`.", "How does Query Execution Plan Analysis with `EXPLAIN (ANALYZE, BUFFERS)` scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-29', 'phase-05-lesson-29-acid-properties-write-ahead-logging-wal-m', 'module-7', 29, 'Lesson 7.29: ACID Properties & Write-Ahead Logging (WAL) Mechanics', 'Prerequisites: Phase 0 (Lesson 0.18)', 'Prerequisites: Phase 0 (Lesson 0.18) | Subtopics: 4 items', 'Systems project application', 200, 6, 1370.0, 1450.0, '# Lesson 5.29: ACID Properties & Write-Ahead Logging (WAL) Mechanics

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Phase 0 (Lesson 0.18)
- **Subtopics**:
  - `5.29.1` ACID breakdown: Atomicity, Consistency, Isolation, Durability.
  - `5.29.2` Write-Ahead Logging (WAL): recording transaction changes sequentially to disk before writing dirty pages to table heap.
  - `5.29.3` Checkpoints: flushing dirty shared buffers to disk and advancing WAL restart checkpoints.
  - `5.29.4` Crash recovery: redo log replaying committed transactions; undo log discarding uncommitted transactions.
- **Key Failure Modes & Edge Cases**: Disabling `fsync` or setting `synchronous_commit = off` without understanding potential data loss on sudden power failure.
- **Verification & Mastery Check**: Trace WAL generation and checkpoint frequency during a high-throughput write load in PostgreSQL.
- **Project Application**: Database reliability engineering.', '{"solution.py": "# Phase 5 // Lesson 5.29: ACID Properties & Write-Ahead Logging (WAL) Mechanics\n\ndef solve():\n    \"\"\"\n    Verification: Trace WAL generation and checkpoint frequency during a high-throughput write load in PostgreSQL.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.29", "subtopics_count": 4, "verification_criteria": "Trace WAL generation and checkpoint frequency during a high-throughput write load in PostgreSQL.", "subtopics": ["5.29.1 ACID breakdown: Atomicity, Consistency, Isolation, Durability.", "5.29.2 Write-Ahead Logging (WAL): recording transaction changes sequentially to disk before writing dirty pages to table heap.", "5.29.3 Checkpoints: flushing dirty shared buffers to disk and advancing WAL restart checkpoints.", "5.29.4 Crash recovery: redo log replaying committed transactions; undo log discarding uncommitted transactions."]}'::jsonb, '["Explain how this implementation prevents: Disabling `fsync` or setting `synchronous_commit = off` without understanding potential data loss on sudden power failur", "How does ACID Properties & Write-Ahead Logging (WAL) Mechanics scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb),
('node-5-30', 'phase-05-lesson-30-concurrency-read-anomalies-dirty-non-repe', 'module-7', 30, 'Lesson 7.30: Concurrency Read Anomalies: Dirty, Non-Repeatable, & Phantom', 'Prerequisites: Lesson 5.29', 'Prerequisites: Lesson 5.29 | Subtopics: 4 items', 'Systems project application', 200, 6, 1250.0, 1500.0, '# Lesson 5.30: Concurrency Read Anomalies: Dirty, Non-Repeatable, & Phantom

- **Status**: `[State: Active | Complete Specification | Core]`
- **Prerequisites**: Lesson 5.29
- **Subtopics**:
  - `5.30.1` Dirty Read: reading data written by an uncommitted, concurrent transaction that subsequently rolls back.
  - `5.30.2` Non-Repeatable Read (Fuzzy Read): re-reading a row within a transaction and finding data modified by another committed transaction.
  - `5.30.3` Phantom Read: re-executing a range query and finding newly inserted rows committed by another transaction.
  - `5.30.4` The ANSI SQL Isolation Level Matrix: mapping isolation levels to permitted anomalies.
- **Key Failure Modes & Edge Cases**: Relying on default isolation levels and experiencing silent data corruption during concurrent inventory allocation.
- **Verification & Mastery Check**: Reproduce a non-repeatable read anomaly between two concurrent database sessions using Python.
- **Project Application**: AuthForge: Account consistency.', '{"solution.py": "# Phase 5 // Lesson 5.30: Concurrency Read Anomalies: Dirty, Non-Repeatable, & Phantom\n\ndef solve():\n    \"\"\"\n    Verification: Reproduce a non-repeatable read anomaly between two concurrent database sessions using Python.\n    \"\"\"\n    pass\n"}'::jsonb, '{"lesson": "5.30", "subtopics_count": 4, "verification_criteria": "Reproduce a non-repeatable read anomaly between two concurrent database sessions using Python.", "subtopics": ["5.30.1 Dirty Read: reading data written by an uncommitted, concurrent transaction that subsequently rolls back.", "5.30.2 Non-Repeatable Read (Fuzzy Read): re-reading a row within a transaction and finding data modified by another committed transaction.", "5.30.3 Phantom Read: re-executing a range query and finding newly inserted rows committed by another transaction.", "5.30.4 The ANSI SQL Isolation Level Matrix: mapping isolation levels to permitted anomalies."]}'::jsonb, '["Explain how this implementation prevents: Relying on default isolation levels and experiencing silent data corruption during concurrent inventory allocation.", "How does Concurrency Read Anomalies: Dirty, Non-Repeatable, & Phantom scale under memory and concurrency constraints?", "Defend the architectural tradeoffs of this design in production."]'::jsonb)
